"""Fit test helpers (WP11): synthetic rig data generated by a fit twin at known values, and a split-guard dataset.

`twin_dataset` runs the twin once at `truth` per condition (the twin's own worlds per condition) and turns the
per-condition mean of each metric into calib/valid trials with Gaussian noise; FIT-3 recovers `truth` from them.
`guarded` replaces every `valid` trial by a `GuardedTrial` that raises `SplitError` on any field but `split` while
the guard is armed, so a test proves the search never touches valid data before the final validation.
"""

from __future__ import annotations

import copy
from collections.abc import Callable, Mapping, Sequence
from dataclasses import dataclass, field, replace
from typing import Any

import numpy as np

from alloy.bench.runner import RunContext, plan_worlds, step_twin
from alloy.bench.types import Condition, LawSpec, RigCard, RigDataset, RigTrial
from alloy.core.ids import digest_of
from alloy.fit.errors import SplitError


@dataclass(frozen=True)
class SyntheticSpec:
    """How to turn twin truth into a dataset."""

    noise: Mapping[str, float]                 # 1-sigma per metric (absolute, law units); also the instrument u95
    trials_per_condition: int = 20
    calib_per_condition: int = 10
    seed: int = 0
    dataset_id: str = "twin-synthetic"


def twin_truth(law: LawSpec, twin: Any, truth: Mapping[str, float], conditions: Sequence[Condition], *,
               solver: str, device: str) -> dict[str, dict[str, float]]:
    """Per condition, per metric: the twin's mean scalar with `truth` fixed (twin hooks: fix_values, scalars)."""
    tw = copy.deepcopy(twin)
    tw.fix_values(dict(truth))
    ctx = RunContext(law, device, 0, solver, False)
    worlds = plan_worlds(law, tuple(conditions), ctx, getattr(tw, "expand", None))
    run = step_twin(law, tw, worlds, ctx)
    values = tw.scalars(run.log)
    ids = np.array([w.condition.id for w in worlds])
    return {c.id: {m: float(np.mean(np.asarray(v, np.float64)[ids == c.id])) for m, v in values.items()}
            for c in conditions}


def twin_dataset(law: LawSpec, twin: Any, truth: Mapping[str, float], conditions: Sequence[Condition],
                 spec: SyntheticSpec, *, solver: str, device: str) -> RigDataset:
    """A RigDataset of `spec.trials_per_condition` noisy copies of the twin's output at `truth` per condition."""
    means = twin_truth(law, twin, truth, conditions, solver=solver, device=device)
    rng = np.random.default_rng(spec.seed)
    trials = []
    for c in conditions:
        for k in range(spec.trials_per_condition):
            scalars = {m: v + float(spec.noise.get(m, 0.0)) * float(rng.standard_normal())
                       for m, v in means[c.id].items() if m in law.metrics}
            split = "calib" if k < spec.calib_per_condition else "valid"
            trials.append(RigTrial(c.id, k, split, {"t": np.linspace(0.0, 1.0, 11)}, scalars))
    inst = {m: {"u95": float(s), "what": "synthetic noise sigma"} for m, s in spec.noise.items()}
    card = RigCard(law.id, spec.dataset_id, "synthetic-twin/1", {}, inst, {}, {})
    sha = digest_of({"law": law.id, "truth": dict(truth), "solver": solver, "means": means,
                     "trials": [(t.condition_id, t.index, t.split, dict(t.scalars)) for t in trials]})
    return RigDataset(card, tuple(conditions), tuple(trials), sha)


@dataclass
class SplitGuard:
    """Armed: any read of a valid trial's data raises SplitError and is recorded."""

    armed: bool = True
    touched: list[str] = field(default_factory=list)


class GuardedTrial:
    """A valid trial whose fields (all but `split`) raise while the guard is armed."""

    def __init__(self, trial: RigTrial, guard: SplitGuard) -> None:
        self._trial, self._guard = trial, guard

    @property
    def split(self) -> str:
        return self._trial.split

    def _read(self, name: str) -> Any:
        if self._guard.armed:
            self._guard.touched.append(f"{self._trial.condition_id}#{self._trial.index}.{name}")
            raise SplitError(f"valid trial {self._trial.condition_id}#{self._trial.index}.{name} read before "
                             "the final validation")
        return getattr(self._trial, name)

    condition_id = property(lambda self: self._read("condition_id"))
    index = property(lambda self: self._read("index"))
    series = property(lambda self: self._read("series"))
    scalars = property(lambda self: self._read("scalars"))


def guarded(data: RigDataset, guard: SplitGuard | None = None) -> tuple[RigDataset, SplitGuard]:
    """`data` with every valid trial wrapped in a GuardedTrial; returns (dataset, guard)."""
    g = guard or SplitGuard()
    trials = tuple(GuardedTrial(t, g) if t.split == "valid" else t for t in data.trials)
    return replace(data, trials=trials), g  # type: ignore[arg-type]


def disarm_on(fn: Callable[..., Any], guard: SplitGuard) -> Callable[..., Any]:
    """Wrap `fn` (the fitter's validate) so the guard disarms when it is entered."""
    def wrapper(*args: Any, **kwargs: Any) -> Any:
        guard.armed = False
        return fn(*args, **kwargs)
    return wrapper


__all__ = ["SyntheticSpec", "twin_truth", "twin_dataset", "SplitGuard", "GuardedTrial", "guarded", "disarm_on"]
